#!/usr/bin/env python3
"""
ABRAXAS UX ARCHITECTURE RESET
Run from project root: python3 fix_ux_arch.py

CHANGES:
  app/terminal/page.tsx
    - 5 views (home/onboarding/trust/flagship/terminal) → 4 tabs
    - New structure: OVERVIEW | COLLATERAL | LENDING | PROTOCOL
    - OVERVIEW: economics inline, protocol metrics, verification pipeline, revenue model
    - COLLATERAL: Genesis Asset + Terminal merged into single workspace (Featured/Registry)
    - LENDING: BorrowPage with LTV schedule
    - PROTOCOL: Asset owner onboarding + Trust architecture
    - Language selector removed from nav (non-functional control)
    - Single auth point: CompactWallet only
    - Economics surfaced immediately on OVERVIEW (not buried at /economics)
    - Cielo Sunrise callout on OVERVIEW with link to COLLATERAL

  components/LanguageSelector.tsx
    - Returns null — non-functional control removed from UI
    - Preserved as stub to avoid import errors
    - No dead buttons visible to users

  components/terminal/TerminalLayout.tsx
    - Empty state: "NO ASSETS REGISTERED" replaced with actionable guidance
    - Lists required documentation for verification
    - Points users to PROTOCOL tab
"""
import base64, os, sys, glob

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "app/terminal/page.tsx": "",
    "components/LanguageSelector.tsx": "",
    "components/terminal/TerminalLayout.tsx": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

for f in glob.glob("fix_*.py"):
    if f != "fix_ux_arch.py":
        os.remove(f); print(f"REMOVED  {f}")

print("""
Run:
  npm run build
  git add -A
  git commit -m "refactor: 4-tab terminal, economics on overview, merged collateral, removed dead controls"
  git push origin main

Navigation after deploy:
  /terminal → OVERVIEW (default)
    Shows: protocol positioning, metrics, verification pipeline, revenue model
  /terminal → COLLATERAL
    FEATURED ASSET: Cielo Sunrise Genesis Asset
    ASSET TERMINAL: 3-column inspector
  /terminal → LENDING
    BorrowPage with LTV schedule
  /terminal → PROTOCOL
    SUBMIT AN ASSET: Owner onboarding (4 steps, no wallet)
    TRUST ARCHITECTURE: 7-layer trust stack
""")
